let kickDanmakuGetStatus = () => ({ state: "idle" });

const kickDanmakuApi = "https://web.kick.com/api/v1/realtime";

function kickDanmakuJson(text) {
  if (typeof text !== "string") return text;
  try {
    return JSON.parse(text);
  } catch {
    return null;
  }
}

function kickDanmakuId(value) {
  if (typeof value === "string" && value.trim()) return value;
  return Number.isSafeInteger(value) && value > 0 ? String(value) : null;
}

function kickDanmakuEvent(publication) {
  const envelope = kickDanmakuJson(publication?.data);
  const name = envelope?.event ?? publication?.tags?.event;
  const event = typeof name === "string" ? name.split("\\").at(-1) : "";
  const data = kickDanmakuJson(envelope?.data);
  if (event === "ChatroomClearEvent") return { type: "clear" };
  if (!data || typeof data !== "object") return null;
  if (event === "MessageDeletedEvent") {
    const id = kickDanmakuId(data.message?.id ?? data.message_id ?? data.id);
    return id ? { type: "delete", id } : null;
  }
  if (event !== "ChatMessageEvent") return null;
  const id = kickDanmakuId(data.id);
  const content = typeof data.content === "string" ? data.content.trim() : "";
  if (!id || !content || data.deleted_at || data.deleted || data.is_deleted) return null;
  if (/^\[?\(?\s*(?:message\s+)?deleted by (?:a )?mod(?:erator)?\s*[.!]?\s*\)?\]?$/i.test(content)) return null;
  return {
    type: "message", id, content,
    username: typeof data.sender?.username === "string" ? data.sender.username : "",
    createdAt: Date.parse(data.created_at),
  };
}

async function kickDanmakuRequest(url, signal, body) {
  const options = { signal: AbortSignal.any([signal, AbortSignal.timeout(12000)]), credentials: "omit" };
  if (body) {
    options.method = "POST";
    options.headers = { "Content-Type": "application/json" };
    options.body = JSON.stringify(body);
  }
  const response = await fetch(url, options);
  if (!response.ok) throw new Error(`HTTP ${response.status}`);
  return response.json();
}

class KickDanmakuRealtime {
  constructor(slug, onEvent, onStatus) {
    this.slug = slug;
    this.onEvent = onEvent;
    this.onStatus = onStatus;
    this.abort = new AbortController();
    this.retryDelay = 1000;
    this.connect();
  }

  stop() {
    this.abort.abort();
    clearTimeout(this.retryTimer);
    this.endSocket?.();
  }

  retry(httpOrSocketError = "") {
    if (this.abort.signal.aborted) return;
    this.onStatus("retry", httpOrSocketError);
    this.retryTimer = setTimeout(() => this.connect(), this.retryDelay * (1 + Math.random() * 0.25));
    this.retryDelay = Math.min(this.retryDelay * 2, 30000);
  }

  async connect() {
    const { signal } = this.abort;
    this.onStatus("connecting");
    try {
      if (!this.room) {
        const channel = await kickDanmakuRequest(`/api/v2/channels/${this.slug}`, signal);
        const id = kickDanmakuId(channel.id);
        const room = kickDanmakuId(channel.chatroom?.id);
        if (!/^\d+$/.test(id ?? "") || !/^\d+$/.test(room ?? "")) throw new Error("找不到聊天室");
        this.channelId = id;
        this.room = `chatrooms.${room}.v2`;
      }
      const clientId = crypto.randomUUID();
      const getToken = async () => {
        const auth = await kickDanmakuRequest(`${kickDanmakuApi}/auth/connection`, signal, { client_id: clientId });
        const token = auth.data?.token;
        if (typeof token !== "string" || !token) throw new Error("缺少访客令牌");
        return token;
      };
      const [server, token] = await Promise.all([
        kickDanmakuRequest(`${kickDanmakuApi}/channels/${this.channelId}/chat/connection`, signal, {
          client: { id: clientId, type: "web" },
          capabilities: { accepted_providers: [{ provider: "centrifugo" }] },
        }),
        getToken(),
      ]);
      if (signal.aborted) return;
      const endpoint = server.data?.connections?.find(entry => entry.provider === "centrifugo")?.credentials?.url;
      const url = endpoint ? new URL(endpoint) : null;
      if (url?.protocol !== "wss:" || !/^realtime\.[a-z0-9-]+\.platform\.kick\.com$/.test(url.hostname)) {
        throw new Error("Kick 未返回实时聊天地址");
      }
      this.openSocket(url, token, getToken);
    } catch (error) {
      this.retry(error.message);
    }
  }

  openSocket(url, token, getToken) {
    const ws = new WebSocket(url);
    let subscribed = false;
    let pong = false;
    let heartbeatMs = 0;
    let heartbeatTimer;
    let refreshTimer;
    let commandTimer;
    let ended = false;
    const finish = (reason) => {
      if (ended) return;
      ended = true;
      clearTimeout(heartbeatTimer);
      clearTimeout(refreshTimer);
      clearTimeout(commandTimer);
      this.endSocket = null;
      ws.close();
      this.retry(reason);
    };
    this.endSocket = finish;
    const commandTimeout = () => {
      clearTimeout(commandTimer);
      commandTimer = setTimeout(() => finish("实时聊天响应超时"), 12000);
    };
    const resetHeartbeat = () => {
      clearTimeout(heartbeatTimer);
      if (heartbeatMs) heartbeatTimer = setTimeout(() => finish("实时聊天连接超时"), heartbeatMs);
    };
    const scheduleRefresh = (result) => {
      clearTimeout(refreshTimer);
      if (!result.expires || !(result.ttl > 0)) return;
      refreshTimer = setTimeout(async () => {
        try {
          const nextToken = await getToken();
          if (ended || ws.readyState !== WebSocket.OPEN) return;
          ws.send(JSON.stringify({ id: 3, refresh: { token: nextToken } }));
          commandTimeout();
        } catch {
          finish("访客令牌续期失败");
        }
      }, Math.max(1000, result.ttl * 1000 - 60000));
    };
    commandTimeout();
    ws.addEventListener("open", () => {
      if (ended) return;
      ws.send(JSON.stringify({ id: 1, connect: { token, name: "js" } }));
      commandTimeout();
    });
    ws.addEventListener("message", ({ data }) => {
      if (ended || typeof data !== "string") return;
      resetHeartbeat();
      for (const line of data.split("\n")) {
        if (ended) break;
        const packet = kickDanmakuJson(line);
        if (!packet || typeof packet !== "object") continue;
        if (Object.keys(packet).length === 0 && pong) ws.send("{}");
        if (packet.error) {
          finish(`实时聊天错误 ${packet.error.code ?? ""}`.trim());
          continue;
        }
        if (packet.id === 1 && packet.connect) {
          pong = packet.connect.pong === true;
          heartbeatMs = packet.connect.ping > 0 ? packet.connect.ping * 1000 + 12000 : 0;
          resetHeartbeat();
          scheduleRefresh(packet.connect);
          ws.send(JSON.stringify({ id: 2, subscribe: { channel: this.room } }));
          commandTimeout();
        } else if (packet.id === 2 && packet.subscribe) {
          clearTimeout(commandTimer);
          subscribed = true;
          this.retryDelay = 1000;
          this.onStatus("live");
        } else if (packet.id === 3 && packet.refresh) {
          clearTimeout(commandTimer);
          scheduleRefresh(packet.refresh);
        }
        if (packet.push?.disconnect || (packet.push?.channel === this.room && packet.push.unsubscribe)) {
          finish("实时聊天订阅已断开");
        }
        if (subscribed && packet.push?.channel === this.room && !ended) {
          const event = kickDanmakuEvent(packet.push.pub);
          if (event) this.onEvent(event);
        }
      }
    });
    ws.addEventListener("close", ({ code }) => finish(`连接已关闭 (${code})`));
    ws.addEventListener("error", () => finish("WebSocket 连接失败"));
  }
}

(() => {
  if (!kickDanmakuPageActive) return;
  const maxAge = 2200;
  const moderationDelay = 450;
  const layer = document.createElement("div");
  layer.id = "kick-danmaku-overlay";
  layer.setAttribute("aria-hidden", "true");

  let settings = kickDanmakuSettings();
  let blocked = [];
  let loaded = false;
  let channel = "";
  let realtime;
  let status = { state: "idle", detail: "" };
  let cutoff = 0;
  let video;
  let width = 0;
  let height = 0;
  let lanes = [];
  let queue = [];
  const active = new Map();
  const seen = new Map();

  function removeMessage(id) {
    const item = active.get(id);
    if (!item) return;
    active.delete(id);
    item.animation.cancel();
    item.node.remove();
    if (item.lane.tail === item) item.lane.tail = null;
  }

  function clearActive() {
    for (const id of active.keys()) removeMessage(id);
    lanes = [];
  }

  function clearOverlay() {
    clearActive();
    queue = [];
  }

  function currentChannel() {
    return location.pathname.match(/^\/([a-z0-9_-]+)\/?$/i)?.[1].toLowerCase() ?? "";
  }

  function visibleVideo(root) {
    const player = root.querySelector("video#video-player, #video-player video");
    if (player?.getBoundingClientRect().width > 120) return player;
    return [...root.querySelectorAll("video")]
      .map(node => ({ node, rect: node.getBoundingClientRect() }))
      .filter(({ rect }) => rect.width > 240 && rect.height > 135)
      .sort((a, b) => b.rect.width * b.rect.height - a.rect.width * a.rect.height)[0]?.node;
  }

  function syncPlayer() {
    const fullscreen = document.fullscreenElement;
    const scope = fullscreen ?? document;
    if (!video?.isConnected || !scope.contains(video) || video.clientWidth <= 120) {
      video = visibleVideo(scope);
    }
    // A bare fullscreen <video> cannot paint DOM children. Kick's player button
    // fullscreens the player container, which can host the overlay.
    if (!video || fullscreen instanceof HTMLVideoElement || video === document.pictureInPictureElement) {
      layer.remove();
      return;
    }
    const rect = video.getBoundingClientRect();
    if (rect.width <= 120 || rect.height <= 70 || rect.bottom <= 0 || rect.right <= 0 ||
        rect.top >= innerHeight || rect.left >= innerWidth) {
      layer.remove();
      return;
    }
    const previousWidth = width;
    width = Math.round(rect.width);
    height = Math.round(rect.height);
    // Kick puts its video wrapper in fullscreen. Keeping the overlay in that
    // wrapper lets the same elements stay connected across the transition.
    const wrapper = video.matches("#video-player") && video.closest("#injected-channel-player")
      ? video.parentElement : null;
    const anchored = wrapper && (!fullscreen || fullscreen.contains(wrapper));
    const host = anchored ? wrapper : fullscreen ?? document.body;
    if (layer.parentNode !== host) host.append(layer);
    const origin = anchored ? host.getBoundingClientRect() : { left: 0, top: 0 };
    layer.style.position = anchored ? "absolute" : "fixed";
    layer.style.left = `${Math.round(rect.left - origin.left)}px`;
    layer.style.top = `${Math.round(rect.top - origin.top)}px`;
    layer.style.width = `${width}px`;
    layer.style.height = `${height}px`;
    const laneCount = Math.max(1, Math.floor((height * settings.area / 100 - 10) / laneHeight()));
    if (lanes.length > laneCount) {
      const removedLanes = new Set(lanes.splice(laneCount));
      for (const [id, item] of active) if (removedLanes.has(item.lane)) removeMessage(id);
    }
    while (lanes.length < laneCount) lanes.push({ tail: null });
    if (previousWidth !== width) {
      for (const item of active.values()) updateMotion(item);
    }
  }

  function laneHeight() {
    return Math.ceil(settings.size * 1.35) + 5;
  }

  function remember(id) {
    if (seen.has(id)) seen.delete(id);
    seen.set(id, true);
    if (seen.size > 3000) seen.delete(seen.keys().next().value);
  }

  function isBlocked(message) {
    const normalized = kickDanmakuFilter(message.content);
    return blocked.some(word => normalized.includes(word));
  }

  function onEvent(event) {
    if (event.type === "clear") {
      cutoff = Date.now();
      clearOverlay();
      return;
    }
    if (event.type === "delete") {
      remember(event.id);
      queue = queue.filter(message => message.id !== event.id);
      removeMessage(event.id);
      return;
    }
    if (seen.has(event.id) || (Number.isFinite(event.createdAt) && event.createdAt < cutoff)) return;
    remember(event.id);
    if (document.hidden || isBlocked(event)) return;
    queue.push({ ...event, receivedAt: performance.now() });
    if (queue.length > 32) queue.shift();
  }

  function isOwnMessage(username) {
    if (!username) return false;
    const accounts = document.querySelectorAll('nav button[aria-haspopup="menu"][aria-label]');
    for (const button of accounts) {
      const name = button.getAttribute("aria-label").trim().toLowerCase();
      const avatar = button.querySelector("img[alt]")?.alt.trim().toLowerCase();
      if (name && name === avatar) return name === username.trim().toLowerCase();
    }
    return false;
  }

  function createMessage(message) {
    const node = document.createElement("span");
    node.className = "kick-danmaku-message";
    node.style.fontWeight = settings.fontWeight;
    if (settings.highlightOwn && isOwnMessage(message.username)) {
      node.classList.add("kick-danmaku-own-message");
    }
    if (settings.showName && message.username) node.append(`${message.username}: `);
    const parts = message.content.split(/\[emote:(\d+):([^\]\r\n]+)\]/g);
    node.append(parts[0]);
    for (let index = 1; index < parts.length; index += 3) {
      const img = document.createElement("img");
      img.src = `https://files.kick.com/emotes/${parts[index]}/fullsize`;
      img.alt = parts[index + 1];
      img.referrerPolicy = "no-referrer";
      node.append(img, parts[index + 2]);
    }
    return node;
  }

  function updateMotion(item) {
    const nodeWidth = Math.ceil(item.node.getBoundingClientRect().width);
    const distance = width + nodeWidth;
    const duration = distance / settings.speed * 1000;
    const keyframes = [{ transform: "translateX(0)" }, { transform: `translateX(-${distance}px)` }];
    if (item.animation) {
      // Updating the end point and duration together preserves pixels per
      // second and the distance this message has traveled from the right edge.
      item.animation.effect.setKeyframes(keyframes);
      item.animation.effect.updateTiming({ duration });
    } else {
      item.animation = item.node.animate(keyframes, { duration, fill: "both" });
    }
    item.entryTime = (nodeWidth + 28) / settings.speed * 1000;
  }

  function launch(message, lane, index) {
    const node = createMessage(message);
    node.style.top = `${10 + index * laneHeight()}px`;
    layer.append(node);
    const item = { node, lane, message };
    updateMotion(item);
    lane.tail = item;
    active.set(message.id, item);
    item.animation.onfinish = () => removeMessage(message.id);
  }

  function tick() {
    if (!loaded) return;
    const slug = settings.enabled ? currentChannel() : "";
    if (slug !== channel) {
      realtime?.stop();
      realtime = undefined;
      channel = slug;
      video = undefined;
      cutoff = Date.now() - 2000;
      seen.clear();
      clearOverlay();
      layer.remove();
    }
    if (!channel) return;
    syncPlayer();
    if (video && !realtime) {
      realtime = new KickDanmakuRealtime(channel, event => {
        if (currentChannel() === slug) onEvent(event);
      }, (state, detail) => {
        status = { state, detail };
      });
    }
    if (document.hidden) {
      clearOverlay();
      return;
    }
    const now = performance.now();
    while (queue.length && now - queue[0].receivedAt > maxAge) queue.shift();
    // Launch at most one per tick even if a burst arrives on an empty screen.
    if (!layer.isConnected || !queue.length || now - queue[0].receivedAt < moderationDelay) return;
    const index = lanes.findIndex(({ tail }) => !tail || tail.animation.currentTime >= tail.entryTime);
    if (index !== -1) launch(queue.shift(), lanes[index], index);
  }

  function applySettings(value) {
    const previous = settings;
    settings = kickDanmakuSettings(value);
    blocked = kickDanmakuFilter(settings.blocked).split(/[\r\n,，]+/).map(word => word.trim()).filter(Boolean);
    layer.style.fontFamily = kickDanmakuFonts[settings.font];
    layer.style.fontSize = `${settings.size}px`;
    layer.style.fontWeight = settings.fontWeight;
    layer.style.color = settings.color;
    layer.style.opacity = settings.opacity / 100;
    if (["size", "speed", "font", "fontWeight", "area", "showName", "highlightOwn"].some(key => previous[key] !== settings[key])) {
      clearActive();
    }
    if (previous.blocked !== settings.blocked) {
      queue = queue.filter(message => !isBlocked(message));
      for (const [id, item] of active) if (isBlocked(item.message)) removeMessage(id);
    }
    loaded = true;
    tick();
  }

  kickDanmakuStore.subscribe(applySettings);
  kickDanmakuStore.get().then(danmaku => {
    if (!loaded) applySettings(danmaku);
  }).catch(() => {
    if (!loaded) applySettings();
  });
  kickDanmakuGetStatus = () => !settings.enabled ? { state: "disabled" } : realtime ? status : { state: "idle" };
  if (!kickDanmakuUserscript) {
    chrome.runtime.onMessage.addListener((message, _sender, reply) => {
      if (message?.type === "kick-danmaku-status") reply(kickDanmakuGetStatus());
    });
  }
  document.addEventListener("fullscreenchange", tick);
  document.addEventListener("visibilitychange", () => {
    if (document.hidden) clearOverlay();
    else tick();
  });
  setInterval(tick, 100);
})();

(() => {
  if (!kickDanmakuPageActive) return;
  const dock = document.createElement("div");
  dock.id = "kick-danmaku-composer";
  dock.setAttribute("role", "region");
  dock.setAttribute("aria-label", "播放器聊天");
  const slot = document.createElement("div");
  slot.className = "kick-danmaku-composer-slot";
  slot.setAttribute("aria-hidden", "true");

  let footer;
  let originalParent;
  let originalNext;
  let lastKeepAlive = 0;
  let caretFrame = 0;
  let composingEditor;

  function scheduleCaretScroll() {
    const editor = document.activeElement;
    if (caretFrame || !dock.contains(editor) || !editor.matches('#chat-input-wrapper [contenteditable="true"]')) return;

    // Lexical can update its selection after the input event, especially on paste.
    caretFrame = requestAnimationFrame(() => {
      caretFrame = 0;
      if (document.activeElement !== editor || editor.scrollWidth <= editor.clientWidth) return;
      const selection = document.getSelection();
      if (!selection?.isCollapsed || !selection.rangeCount || !editor.contains(selection.focusNode)) return;
      const caret = selection.getRangeAt(0).getClientRects()[0];
      if (!caret) return;

      const edgePadding = 8;
      const left = editor.getBoundingClientRect().left + editor.clientLeft + edgePadding;
      const right = left + editor.clientWidth - 2 * edgePadding;
      if (caret.right > right) editor.scrollLeft += Math.ceil(caret.right - right);
      else if (caret.left < left) editor.scrollLeft -= Math.ceil(left - caret.left);
    });
  }

  function move(node, parent, next = null) {
    // Chrome and Edge preserve the editor's focus and selection with moveBefore.
    if (parent.moveBefore && node.isConnected && parent.isConnected) {
      parent.moveBefore(node, next);
    } else {
      const focus = node.contains(document.activeElement) ? document.activeElement : null;
      parent.insertBefore(node, next);
      if (parent.isConnected) focus?.focus({ preventScroll: true });
    }
  }

  function restore() {
    if (!footer) return;
    if (footer.parentNode === dock) {
      move(footer, originalParent, originalNext?.parentNode === originalParent ? originalNext : null);
    }
    dock.remove();
    slot.remove();
    composingEditor = undefined;
    footer = undefined;
    originalParent = undefined;
    originalNext = undefined;
  }

  function update() {
    const player = document.querySelector("#injected-channel-player video#video-player");
    const fullscreen = document.fullscreenElement;
    const videoWrapper = player?.parentElement;
    const useFullscreen = player && fullscreen && fullscreen !== player && fullscreen.contains(player);
    const chatCollapsed = player && !fullscreen && player.closest('[data-chat="false"]');
    if (!useFullscreen && !chatCollapsed) {
      restore();
      return;
    }

    const row = videoWrapper.querySelector(":scope > div > .grid-row-2 > .z-controls");
    const hasSlot = row?.firstElementChild?.nextElementSibling && (!useFullscreen || fullscreen.contains(row));
    const interacting = dock.contains(document.activeElement) || composingEditor;
    if (!hasSlot && (!interacting || dock.parentNode !== videoWrapper)) {
      restore();
      return;
    }

    const nativeFooter = document.querySelector("#channel-chatroom #chatroom-footer");
    if (footer && (!originalParent.isConnected || footer.parentNode !== dock || nativeFooter)) {
      restore();
    }
    if (!footer) {
      if (!nativeFooter || nativeFooter.hasAttribute("hidden")) return;
      footer = nativeFooter;
      originalParent = footer.parentNode;
      originalNext = footer.nextSibling;
      dock.style.setProperty("--chatroom-font-size",
        getComputedStyle(footer).getPropertyValue("--chatroom-font-size").trim() || "14px");
    }
    // Kick removes its controls on inactivity. Keep the editor in the stable
    // player wrapper; the controls only carry its layout placeholder.
    if (dock.parentNode !== videoWrapper) move(dock, videoWrapper);
    if (footer.parentNode !== dock) move(footer, dock);
    if (hasSlot) {
      if (slot.parentNode !== row) move(slot, row, row.firstElementChild.nextSibling);
      const position = slot.getBoundingClientRect();
      const wrapper = videoWrapper.getBoundingClientRect();
      dock.style.left = `${position.left - wrapper.left}px`;
      dock.style.top = `${position.top + position.height / 2 - wrapper.top}px`;
      dock.style.width = `${position.width}px`;
    }

    // Preserve the usual behavior for typing without an active IME candidate.
    const now = performance.now();
    if (interacting && !composingEditor && now - lastKeepAlive >= 500) {
      lastKeepAlive = now;
      videoWrapper.dispatchEvent(new MouseEvent("mousemove", { bubbles: true }));
    }
  }

  dock.addEventListener("focusin", scheduleCaretScroll);
  dock.addEventListener("input", scheduleCaretScroll, true);
  dock.addEventListener("compositionstart", event => {
    if (event.target.matches('#chat-input-wrapper [contenteditable="true"]')) composingEditor = event.target;
  });
  dock.addEventListener("compositionend", event => {
    if (event.target !== composingEditor) return;
    const editor = composingEditor;
    queueMicrotask(() => {
      if (editor !== composingEditor) return;
      composingEditor = undefined;
      if (document.fullscreenElement && document.hasFocus() && document.activeElement === document.body) {
        editor.focus({ preventScroll: true });
      }
    });
  });
  window.addEventListener("pointerdown", event => {
    if (!dock.contains(event.target)) composingEditor = undefined;
  }, true);
  function protectComposition(event) {
    if (!document.fullscreenElement || !composingEditor || dock.contains(event.target)) return;
    if (event.target === document.body || event.target === document.documentElement) {
      event.stopImmediatePropagation();
    }
  }
  window.addEventListener("keydown", protectComposition, true);
  window.addEventListener("keyup", protectComposition, true);
  document.addEventListener("selectionchange", scheduleCaretScroll);
  document.addEventListener("fullscreenchange", update);
  window.navigation?.addEventListener("navigate", event => {
    if (new URL(event.destination.url).pathname !== location.pathname) restore();
  });
  window.addEventListener("pagehide", restore);
  setInterval(update, 100);
  update();
})();

function kickDanmakuBindPanel(root, getStatus) {
  const form = root.querySelector("#settings");
  const fields = Object.fromEntries(Object.keys(kickDanmakuDefaults).map(key => [key, root.getElementById(key)]));
  const preview = root.querySelector("#preview");
  const statusLabel = root.querySelector("#status");
  const saveError = root.querySelector("#save-error");
  let writes = Promise.resolve();

  function display(settings) {
    for (const [key, value] of Object.entries(settings)) {
      if (fields[key].type === "checkbox") fields[key].checked = value;
      else fields[key].value = value;
    }
    updatePreview(settings);
  }

  function updatePreview(settings) {
    for (const [key, unit] of Object.entries({ size: " px", opacity: "%", speed: " px/s", area: "%" })) {
      form.querySelector(`output[for="${key}"]`).textContent = `${settings[key]}${unit}`;
    }
    preview.style.fontFamily = kickDanmakuFonts[settings.font];
    preview.style.fontSize = `${settings.size}px`;
    preview.style.fontWeight = settings.fontWeight;
    preview.style.color = settings.color;
    preview.style.opacity = settings.opacity / 100;
    preview.classList.toggle("own-message", settings.highlightOwn);
    const label = settings.highlightOwn ? "自己的弹幕" : "弹幕预览";
    preview.textContent = settings.showName ? `我: ${label}` : label;
  }

  function save(settings) {
    updatePreview(settings);
    writes = writes.then(async () => {
      await kickDanmakuStore.set(settings);
      saveError.textContent = "";
    }).catch(() => {
      saveError.textContent = "设置保存失败";
    });
  }

  function readForm() {
    return kickDanmakuSettings(Object.fromEntries(Object.entries(fields).map(([key, field]) => {
      if (field.type === "checkbox") return [key, field.checked];
      if (field.type === "range") return [key, field.valueAsNumber];
      return [key, field.value];
    })));
  }

  async function updateStatus() {
    try {
      const { state, detail } = await getStatus();
      statusLabel.textContent = {
        idle: "等待 Kick 直播播放器",
        connecting: "正在连接实时聊天",
        live: "实时聊天已连接",
        disabled: "弹幕已关闭",
        retry: detail ? `重新连接中 · ${detail}` : "正在重新连接",
      }[state] ?? "等待 Kick 直播播放器";
    } catch {
      statusLabel.textContent = "请打开或刷新 Kick 直播页面";
    }
  }

  form.addEventListener("submit", event => event.preventDefault());
  const reset = root.querySelector("#reset");
  for (const field of [...Object.values(fields), reset]) field.disabled = true;
  kickDanmakuStore.get().then(danmaku => {
    display(kickDanmakuSettings(danmaku));
  }).catch(() => {
    display(kickDanmakuDefaults);
    saveError.textContent = "读取设置失败";
  }).finally(() => {
    for (const field of [...Object.values(fields), reset]) field.disabled = false;
    form.addEventListener("input", () => save(readForm()));
    fields.enabled.addEventListener("input", () => save(readForm()));
    reset.addEventListener("click", () => {
      display(kickDanmakuDefaults);
      save(kickDanmakuDefaults);
    });
  });

  updateStatus();
  const timer = setInterval(updateStatus, 1000);
  return () => clearInterval(timer);
}

